from __future__ import annotations

import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).parents[3] / "services" / "ui"))

from ui.render import to_view
from ui.web import WebPage, frame_src, frame_verdict, normalize


@pytest.mark.parametrize(
    ("url", "src"),
    [
        ("https://www.youtube.com/watch?v=dQw4w9WgXcQ", "https://www.youtube.com/embed/dQw4w9WgXcQ"),
        ("https://www.youtube.com/watch?t=30&v=dQw4w9WgXcQ", "https://www.youtube.com/embed/dQw4w9WgXcQ"),
        ("https://youtu.be/dQw4w9WgXcQ", "https://www.youtube.com/embed/dQw4w9WgXcQ"),
        ("https://www.ssbwiki.com/Little_Mac", "https://www.ssbwiki.com/Little_Mac"),  # no rule: as is
    ],
)
def test_a_rule_rewrites_its_links_others_load_as_they_are(url: str, src: str) -> None:
    assert frame_src(url) == src


def test_an_address_without_a_scheme_gets_https() -> None:
    assert normalize(" ssbwiki.com/Little_Mac ") == "https://ssbwiki.com/Little_Mac"
    assert normalize("http://localhost:3000") == "http://localhost:3000"
    assert normalize("") == ""


def test_a_page_is_a_browser_view_named_by_its_host() -> None:
    view = to_view(WebPage(url="https://www.ssbwiki.com/Little_Mac"))
    assert (view.kind, view.summary) == ("browser", "www.ssbwiki.com")
    assert view.data(slot="tab:web").web == {
        "url": "https://www.ssbwiki.com/Little_Mac",
        "src": "https://www.ssbwiki.com/Little_Mac",
        "host": "www.ssbwiki.com",
        "frameable": "unknown",
        "why": "",
    }
    assert to_view(WebPage()).summary == "blank"
    refused = WebPage(url="https://github.com", frameable=False, why="x-frame-options: deny")
    assert to_view(refused).data(slot="tab:web").web["frameable"] == "no"


@pytest.mark.parametrize(
    ("xfo", "csp", "ok"),
    [
        ("deny", "", False),  # github.com
        ("SAMEORIGIN", "", False),
        ("", "default-src 'self'; frame-ancestors 'none'; img-src *", False),
        ("", "frame-ancestors 'self' https://example.com", False),  # only listed sites
        ("", "frame-ancestors *", True),
        ("", "default-src 'self'", True),  # no frame rule
        ("", "", True),
    ],
)
def test_frame_verdict_reads_both_headers(xfo: str, csp: str, ok: bool) -> None:
    assert frame_verdict(xfo, csp)[0] is ok
